func UpdatedAtLT(v time.Time) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(sql.FieldLT(FieldUpdatedAt, v))
}

// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(sql.FieldLTE(FieldUpdatedAt, v))
}

// HasProductSubscriptions applies the HasEdge predicate on the "product_subscriptions" edge.
func HasProductSubscriptions() predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ProductSubscriptionsTable, ProductSubscriptionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProductSubscriptionsWith applies the HasEdge predicate on the "product_subscriptions" edge with a given conditions (other predicates).
func HasProductSubscriptionsWith(preds ...predicate.ProductSubscription) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(func(s *sql.Selector) {
		step := newProductSubscriptionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ServiceChargePlan) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ServiceChargePlan) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ServiceChargePlan) predicate.ServiceChargePlan {
	return predicate.ServiceChargePlan(sql.NotPredicates(p))
}
